  3	public final class CircularQueueTest {
  4	
  5	    @FunctionalInterface
  6	    interface ThrowingRunnable {
  7	        void run() throws Exception;
  8	    }
  9	
 10	    private CircularQueueTest() {
 11	    }
 12	
 13	    public static void main(String[] args) {
 14	        testBasicQueueOperations();
 15	        testWrapAroundBehavior();
 16	        testCapacityBoundaries();
 17	        testClearAndRemainingCapacity();
 18	        testIteratorTraversalAndFailFastBehavior();
 19	        testNullElementsAreRejected();
 20	        testLegacyWrapperCompatibility();
 21	        System.out.println("All CircularQueue tests passed.");
 22	    }
 23	
 24	    private static void testBasicQueueOperations() {
 25	        CircularQueue<Integer> queue = new CircularQueue<>(3);
 26	        queue.enqueue(10);
 27	        queue.enqueue(20);
 28	
 29	        assertEquals(Integer.valueOf(2), Integer.valueOf(queue.size()), "enqueue should increase the size");
 30	        assertEquals(Integer.valueOf(1), Integer.valueOf(queue.remainingCapacity()), "remaining capacity should decrease after enqueue");
 31	        assertEquals(Integer.valueOf(10), queue.peek(), "peek should return the front element");
 32	        assertEquals(Integer.valueOf(10), queue.peekFront(), "peekFront should return the front element");
 33	        assertEquals(Integer.valueOf(20), queue.peekRear(), "peekRear should return the rear element");
 34	        assertEquals(Integer.valueOf(10), queue.dequeue(), "dequeue should remove from the front");
 35	        assertEquals(Integer.valueOf(20), queue.poll(), "poll should remove and return the next element");
 36	        assertNull(queue.poll(), "poll should return null when the queue is empty");
 37	        assertThrows(IllegalStateException.class, () -> queue.dequeue(), "dequeue should throw when the queue is empty");
 38	    }
 39	
 40	    private static void testWrapAroundBehavior() {
 41	        CircularQueue<Integer> queue = new CircularQueue<>(3);
 42	        queue.enqueue(1);
 43	        queue.enqueue(2);
 44	        queue.enqueue(3);
 45	        queue.dequeue();
 46	        queue.enqueue(4);
 47	
 48	        assertEquals("[2, 3, 4]", queue.toString(), "wrap-around should preserve iteration order");
 49	        assertEquals(Integer.valueOf(2), queue.peekFront(), "front should advance after dequeue");
 50	        assertEquals(Integer.valueOf(4), queue.peekRear(), "rear should track wrapped insertion");
 51	    }
 52	
 53	    private static void testCapacityBoundaries() {
 54	        CircularQueue<Integer> queue = new CircularQueue<>(2);
 55	        assertTrue(queue.offer(7), "offer should succeed when there is room");
 56	        assertTrue(queue.offer(8), "offer should succeed until the queue is full");
 57	        assertFalse(queue.offer(9), "offer should return false when the queue is full");
 58	        assertThrows(IllegalStateException.class, () -> queue.enqueue(9), "enqueue should throw when the queue is full");
 59	        assertEquals(Integer.valueOf(0), Integer.valueOf(queue.remainingCapacity()), "remaining capacity should be zero when full");
 60	    }
