 62	    private static void testClearAndRemainingCapacity() {
 63	        CircularQueue<String> queue = new CircularQueue<>(2);
 64	        queue.enqueue("a");
 65	        queue.enqueue("b");
 66	        queue.clear();
 67	
 68	        assertTrue(queue.isEmpty(), "clear should empty the queue");
 69	        assertEquals(Integer.valueOf(2), Integer.valueOf(queue.remainingCapacity()), "clear should restore the full remaining capacity");
 70	        assertEquals("[]", queue.toString(), "clear should reset the string representation");
 71	    }
