 73	    private static void testIteratorTraversalAndFailFastBehavior() {
 74	        CircularQueue<Integer> queue = new CircularQueue<>(4);
 75	        queue.enqueue(5);
 76	        queue.enqueue(6);
 77	        queue.enqueue(7);
 78	
 79	        StringBuilder visited = new StringBuilder();
 80	        for (Integer value : queue) {
 81	            if (visited.length() > 0) {
 82	                visited.append(',');
 83	            }
 84	            visited.append(value);
 85	        }
 86	        assertEquals("5,6,7", visited.toString(), "iterator should traverse from head to tail");
 87	
 88	        Iterator<Integer> iterator = queue.iterator();
 89	        assertTrue(iterator.hasNext(), "iterator should have elements before mutation");
 90	        queue.dequeue();
 91	        assertThrows(java.util.ConcurrentModificationException.class, () -> iterator.hasNext(), "iterator should fail fast after queue mutation");
 92	    }
